-- Restore the tracker annotations from the 2026-07-25 export (Postgres).
--
-- The app creates its own tables on first run, so just paste this into the SQL
-- console of the Postgres store (Vercel → Storage → your database → Query) after
-- the app has been opened once.
--
-- Safe to re-run: each section replaces the rows it inserts.
-- Restores: 63 PO first-emission dates, 78 partner statuses, 16 comments.
--
-- sla_po_emission is the important one: the payout SLA deadline is measured from
-- the date a PO was first seen. Without it the app falls back to BigQuery's sync
-- timestamp and every payout looks freshly due instead of breached.

-- 1. PO first-emission dates -------------------------------------------------
DELETE FROM sla_po_emission;

-- 2. Partner outreach statuses -----------------------------------------------
DELETE FROM sla_partner_status;

-- 3. Comments ----------------------------------------------------------------
DELETE FROM sla_event_comments WHERE user_id = 'legacy-import';
